<?php
if(!defined('ABSPATH'))exit;
function pl_check($name,$ok){if(!$ok)throw new RuntimeException('FAIL PROOF LIMIT '.$name);echo 'PASS PROOF LIMIT '.$name."\n";}
function pl_order(){ $o=wc_create_order();$o->set_currency('PKR');$o->set_total(1499);$o->set_payment_method('crmp_manual');$o->update_meta_data('_crmp_selected_method','bank');$o->set_status('on-hold');$o->save();return $o; }
function pl_row($o){global $wpdb;$wpdb->insert(crmp_table(),array('order_id'=>$o->get_id(),'method'=>'bank','amount'=>1499,'currency'=>'PKR','transaction_ref'=>'ORIGINAL-'.wp_rand(),'status'=>'pending','submitted_at'=>current_time('mysql'),'payment_date'=>'2026-01-01'));return (int)$wpdb->insert_id;}
wp_set_current_user(1);global $wpdb;update_option('crmp_method_config',array('bank'=>array('enabled'=>'yes','title'=>'Test Bank','account_title'=>'Test','account'=>'TEST')));
delete_option('crmp_proof_update_limit');pl_check('default configurable limit is 3',crmp_proof_update_limit()===3);
foreach(array(0=>1,1=>1,3=>3,10=>10,11=>10,-4=>1) as $raw=>$expected){update_option('crmp_proof_update_limit',$raw);pl_check('limit clamp '.$raw,crmp_proof_update_limit()===$expected);}delete_option('crmp_proof_update_limit');
$o=pl_order();$id=pl_row($o);$d=array('method'=>'bank','payment_date'=>'2026-01-01','customer_note'=>'Corrected');
$old_ref=crmp_get_transaction($id)->transaction_ref;$wpdb->query('ALTER TABLE '.$wpdb->prefix.'crmp_transactions DROP COLUMN replacement_count');update_option('crmp_db_version','9');crmp_install();
pl_check('schema upgrade preserves existing proof and starts quota at zero',get_option('crmp_db_version')==='11'&&crmp_get_transaction($id)->transaction_ref===$old_ref&&(int)crmp_get_transaction($id)->replacement_count===0);
pl_check('initial submission does not consume replacements',(int)crmp_get_transaction($id)->replacement_count===0);
wp_set_current_user(0);$_GET['key']=$o->get_order_key();ob_start();crmp_render_payment_evidence($o);$html=ob_get_clean();pl_check('pending form hidden with explicit update button',str_contains($html,'crmp-proof-toggle')&&preg_match('/<form[^>]+ hidden[^>]+crmp-proof-form/',$html)&&str_contains($html,'you can submit <strong>3</strong> more'));file_put_contents('/tmp/crmp-proof-limit.html',$html);
for($i=1;$i<=3;$i++){delete_transient('crmp_replace_'.$id);$r=crmp_replace_pending_proof($o,$id,$i,'UPDATE-'.$i,null,$d);pl_check('replacement '.$i.' succeeds and increments quota',$r===true&&(int)crmp_get_transaction($id)->replacement_count===$i);}
$before=crmp_get_transaction($id);delete_transient('crmp_replace_'.$id);$blocked=crmp_replace_pending_proof($o,$id,4,'OVER-LIMIT',null,$d);$after=crmp_get_transaction($id);pl_check('fourth replacement blocked without modifying proof',is_wp_error($blocked)&&$blocked->get_error_code()==='crmp_update_limit'&&$before==$after);
ob_start();crmp_render_payment_evidence($o);$limited=ob_get_clean();pl_check('limit reached shows waiting notice without upload form',str_contains($limited,'you can submit <strong>0</strong> more')&&!str_contains($limited,'crmp-proof-form'));
wp_set_current_user(1);pl_check('failed stale admin review does not reset allowance',is_wp_error(crmp_review_transaction($id,'rejected','Stale',999))&&(int)crmp_get_transaction($id)->replacement_count===3);pl_check('admin rejection resets allowance',crmp_review_transaction($id,'rejected','Please correct',4)===true&&(int)crmp_get_transaction($id)->replacement_count===0);
wp_set_current_user(0);ob_start();crmp_render_payment_evidence(wc_get_order($o->get_id()));$rejected_html=ob_get_clean();pl_check('rejected form collapsed with update and cancel buttons',preg_match('/<form[^>]+ hidden[^>]+crmp-proof-form/',$rejected_html)&&str_contains($rejected_html,'crmp-proof-toggle')&&str_contains($rejected_html,'crmp-proof-cancel')&&str_contains($rejected_html,'Please correct'));wp_set_current_user(1);

delete_transient('crmp_replace_'.$id);pl_check('replacement after review uses same ID and new allowance',crmp_replace_pending_proof($o,$id,4,'AFTER-REVIEW',null,$d)===true&&(int)crmp_get_transaction($id)->replacement_count===1&&(int)crmp_get_transaction($id)->proof_version===5);
pl_check('stale request cannot consume allowance',is_wp_error(crmp_replace_pending_proof($o,$id,4,'STALE',null,$d))&&(int)crmp_get_transaction($id)->replacement_count===1);
pl_check('approval resets quota but closes submissions',crmp_review_transaction($id,'verified','Checked',5)===true&&(int)crmp_get_transaction($id)->replacement_count===0&&is_wp_error(crmp_replace_pending_proof($o,$id,5,'PAID',null,$d)));
$bulk_order=pl_order();$bulk_id=pl_row($bulk_order);$wpdb->update(crmp_table(),array('replacement_count'=>3),array('id'=>$bulk_id));$bulk=crmp_bulk_manage(array($bulk_id),'reject','Bulk review',array($bulk_id=>1));pl_check('bulk rejection resets allowance',count($bulk['processed'])===1&&(int)crmp_get_transaction($bulk_id)->replacement_count===0);
foreach(array(1,10) as $cap){update_option('crmp_proof_update_limit',$cap);$co=pl_order();$ci=pl_row($co);$wpdb->update(crmp_table(),array('replacement_count'=>$cap-1),array('id'=>$ci));$last=crmp_replace_pending_proof($co,$ci,1,'CONFIG-LAST-'.$cap,null,$d);$next=crmp_replace_pending_proof($co,$ci,2,'CONFIG-OVER-'.$cap,null,$d);pl_check('configured limit enforced '.$cap,$last===true&&is_wp_error($next)&&$next->get_error_code()==='crmp_update_limit');}
delete_option('crmp_proof_update_limit');
$web=pl_order();$webid=pl_row($web);$wpdb->update(crmp_table(),array('replacement_count'=>2),array('id'=>$webid));$page=wp_insert_post(array('post_title'=>'Proof limit test','post_content'=>'[crmp_release_panel]','post_type'=>'page','post_status'=>'publish'));$f=array('order'=>$web->get_id(),'id'=>$webid,'key'=>$web->get_order_key(),'page'=>$page);update_option('crmp_release_fixture',$f);file_put_contents('/tmp/crmp-proof-limit-fixture.json',wp_json_encode($f));
echo "RESULT: PROOF LIMIT CHECKS PASSED\n";
